fish (k,v,comment) = (* Fish converts some colon-separated vars to arrays, which have to be treated differently. MANPATH is handled automatically, so better not to set it at all when not already defined *) let to_arr_string v = OpamStd.List.concat_map " " (fun v -> if v = Printf.sprintf ""$%s"" k then "$"^k (* remove quotes *) else v) (OpamStd.String.split v ':') in match k with | "PATH" -> Printf.sprintf "%sset -gx %s %s;
" (make_comment comment) k (to_arr_string v) | "MANPATH" -> Printf.sprintf "%sif [ (count $%s) -gt 0 ]; set -gx %s %s; end;
" (make_comment comment) k k (to_arr_string v) | _ -> (* Regular string variables *) Printf.sprintf "%sset -gx %s %s;
" (make_comment comment) k v
